const tickets = $input.all().map(i => i.json).filter(t => t && t._id);
const countBy = (key) => tickets.reduce((acc, t) => { const k = t[key] || 'unassigned'; acc[k] = (acc[k] || 0) + 1; return acc; }, {});
const fmt = (obj) => Object.entries(obj).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k}: ${v}`).join(', ') || 'none';
const categories = countBy('category');
const departments = countBy('department');
const statuses = countBy('status');
return [{ json: {
  total: tickets.length,
  categories, departments, statuses,
  categoryText: fmt(categories), departmentText: fmt(departments), statusText: fmt(statuses),
  resolved: statuses.resolved || 0,
  awaitingApproval: statuses.awaiting_approval || 0,
  escalated: tickets.filter(t => t.escalated === true).length,
  highUrgency: tickets.filter(t => t.urgency === 'high').length,
} }];

